#include <bits/stdc++.h>
using namespace std;

class DStress2_Variant3 {
public:
    int INF = INT_MAX / 3;

    int computeCost(const vector<char>& sequence) {
        vector<int> vPositions, kPositions, otherPositions;
        for (int i = 0; i < (int)sequence.size(); i++) {
            if (sequence[i] == 'V') vPositions.push_back(i);
            else if (sequence[i] == 'K') kPositions.push_back(i);
            else otherPositions.push_back(i);
        }

        int vSize = (int)vPositions.size();
        int kSize = (int)kPositions.size();
        int oSize = (int)otherPositions.size();

        vector<vector<vector<vector<int>>>> dpTable(2,
            vector<vector<vector<int>>>(vSize + 1,
                vector<vector<int>>(kSize + 1,
                    vector<int>(oSize + 1, INF))));

        dpTable[0][0][0][0] = 0;

        for (int vCount = 0; vCount <= vSize; vCount++) {
            for (int kCount = 0; kCount <= kSize; kCount++) {
                for (int oCount = 0; oCount <= oSize; oCount++) {
                    for (int lastFlag = 0; lastFlag < 2; lastFlag++) {
                        int currentCost = dpTable[lastFlag][vCount][kCount][oCount];
                        if (currentCost == INF) continue;

                        if (vCount < vSize) {
                            int newCost = currentCost + count(vPositions[vCount], kCount, kPositions) + count(vPositions[vCount], oCount, otherPositions);
                            dpTable[1][vCount + 1][kCount][oCount] = min(dpTable[1][vCount + 1][kCount][oCount], newCost);
                        }
                        if (kCount < kSize && lastFlag == 0) {
                            int newCost = currentCost + count(kPositions[kCount], vCount, vPositions) + count(kPositions[kCount], oCount, otherPositions);
                            dpTable[0][vCount][kCount + 1][oCount] = min(dpTable[0][vCount][kCount + 1][oCount], newCost);
                        }
                        if (oCount < oSize) {
                            int newCost = currentCost + count(otherPositions[oCount], vCount, vPositions) + count(otherPositions[oCount], kCount, kPositions);
                            dpTable[0][vCount][kCount][oCount + 1] = min(dpTable[0][vCount][kCount][oCount + 1], newCost);
                        }
                    }
                }
            }
        }

        return min(dpTable[0][vSize][kSize][oSize], dpTable[1][vSize][kSize][oSize]);
    }

private:
    int count(int position, int startIdx, const vector<int>& list) {
        int cnt = 0;
        for (int i = startIdx; i < (int)list.size(); i++) {
            if (list[i] < position) cnt++;
        }
        return cnt;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int length;
    string inputStr;
    cin >> length >> inputStr;
    DStress2_Variant3 solver;
    vector<char> seq(inputStr.begin(), inputStr.end());
    cout << solver.computeCost(seq) << "\n";
    return 0;
}

